// =============================================================================
// SINGLE SOURCE OF TRUTH FOR SITE COLORS
// -----------------------------------------------------------------------------
// Edit colors ONLY in COLOR_TOKENS below. Everything else is derived:
//   - COLOR / COLORS / Sanity option lists (this file)
//   - Tailwind class maps (textColorToTailwind, etc.) (this file)
//   - src/app/styles/colors.css (@theme tokens + class safelist), which is
//     regenerated by `npm run colors` (runs automatically before dev/build).
//
// Key = CAPITAL version of the Sanity name ('Purple' in Sanity -> 'PURPLE').
// `tw` = Tailwind name -> creates `--color-<tw>` and `bg-<tw>`, `text-<tw>`, etc.
// =============================================================================
export const COLOR_TOKENS = {
  BLACK: { value: "#000000", tw: "black" },
  WHITE: { value: "#FFFFFF", tw: "white" },

  PRIMARY: { value: "#03CCFF", tw: "primary" },
  PRIMARY_DARK: { value: "#460071", tw: "primary-dark" },
  PRIMARY_LIGHT: { value: "#09FBFF", tw: "primary-light" },
  SECONDARY: { value: "#D403E1", tw: "secondary" },

  BLUE: { value: "#3689D7", tw: "blue" },
  DARKER_BLUE: { value: "#266097", tw: "darker-blue" },

  GRAY: { value: "#C6C6C6", tw: "gray" },
  LIGHT_GRAY: { value: "#F5F5F5", tw: "lightgray" },
  DARK_GRAY: { value: "#777777", tw: "darkgray" },

  ERROR: { value: "#ff0059", tw: "error" },
  ACCENT: { value: "#D403E1", tw: "accent" },
};

/** Flat map of hex values, e.g. COLOR.PRIMARY -> "#03CCFF" */
export const COLOR = Object.fromEntries(
  Object.entries(COLOR_TOKENS).map(([key, { value }]) => [key, value]),
);

export const COLORS = {
  WHITE: { NAME: "White", VALUE: COLOR.WHITE },
  BLACK: { NAME: "Black", VALUE: COLOR.BLACK },
  PRIMARY: { NAME: "Blue", VALUE: COLOR.PRIMARY },
  PRIMARY_DARK: { NAME: "Purple", VALUE: COLOR.PRIMARY_DARK },
  PRIMARY_LIGHT: { NAME: "Light Blue", VALUE: COLOR.PRIMARY_LIGHT },
  SECONDARY: { NAME: "Pink", VALUE: COLOR.SECONDARY },
};

