// ============================================= HELPER MAPS FOR TAILWIND CLASSES
// Used in DefaultWrapper, Text, Svg, etc. Keyed by hex value -> Tailwind class.
// Generated from COLOR_TOKENS. These class names are built dynamically, so
// Tailwind can't see them in source; colors.css safelists them via
// `@source inline(...)` (see scripts/generate-colors.mjs).
const buildClassMap = (prefix) =>
  Object.fromEntries(
    Object.values(COLOR_TOKENS).map(({ value, tw }) => [value, `${prefix}${tw}`]),
  );

export const TAILWIND_COLOR_PREFIXES = [
  "text-",
  "bg-",
  "[&_path]:fill-",
  "[&_path]:stroke-",
];

export const textColorToTailwind = buildClassMap("text-");
export const backgroundToTailwind = buildClassMap("bg-");
export const svgPathFillToTailwind = buildClassMap("[&_path]:fill-");
export const svgPathStrokeToTailwind = buildClassMap("[&_path]:stroke-");
